#include "core.hpp"
#include "feature_advanced_architectures.hpp"
#include <fstream>
#include <iostream>
#include <algorithm>
using namespace scratcher;
namespace {
template<class T>void put(std::vector<uint8_t>& data,size_t pos,T value){std::memcpy(data.data()+pos,&value,sizeof(value));}
void save(const std::filesystem::path&p,const std::vector<uint8_t>&data){std::ofstream out(p,std::ios::binary);out.write(reinterpret_cast<const char*>(data.data()),data.size());}
void check(bool ok,const char*text){if(!ok)throw std::runtime_error(text);}
std::vector<uint8_t> macho(){std::vector<uint8_t>d(0x220);put<uint32_t>(d,0,0xfeedfacf);put<uint32_t>(d,4,0x100000c);put<uint32_t>(d,12,2);put<uint32_t>(d,16,2);put<uint32_t>(d,20,96);put<uint32_t>(d,32,0x19);put<uint32_t>(d,36,72);std::memcpy(d.data()+40,"__TEXT",6);put<uint64_t>(d,56,0x100000000);put<uint64_t>(d,64,d.size());put<uint64_t>(d,72,0);put<uint64_t>(d,80,d.size());put<uint32_t>(d,88,5);put<uint32_t>(d,92,5);put<uint32_t>(d,104,0x80000028);put<uint32_t>(d,108,24);put<uint64_t>(d,112,0x200);put<uint32_t>(d,0x200,0x52800540);put<uint32_t>(d,0x204,0xd65f03c0);return d;}
std::vector<uint8_t> elf(){std::vector<uint8_t>d(0x210);std::memcpy(d.data(),"\x7f" "ELF",4);d[4]=2;d[5]=1;d[6]=1;put<uint16_t>(d,16,2);put<uint16_t>(d,18,183);put<uint32_t>(d,20,1);put<uint64_t>(d,24,0x400200);put<uint64_t>(d,32,64);put<uint16_t>(d,52,64);put<uint16_t>(d,54,56);put<uint16_t>(d,56,1);put<uint32_t>(d,64,1);put<uint32_t>(d,68,5);put<uint64_t>(d,72,0);put<uint64_t>(d,80,0x400000);put<uint64_t>(d,96,d.size());put<uint64_t>(d,104,d.size());put<uint32_t>(d,0x200,0x52800540);put<uint32_t>(d,0x204,0xd65f03c0);return d;}
}
int main(){try{auto path=executableDir()/"architecture-fixture.bin";
auto data=macho();save(path,data);{Engine e;e.open(path);check(e.binary()->format=="Mach-O"&&binaryArchitecture(*e.binary())=="arm64"&&e.binary()->entry==0x100000200,"Mach-O ARM64 load");auto rows=e.disassemble(e.binary()->entry,2);check(rows.size()==2&&rows[0].mnemonic=="MOV"&&rows[1].mnemonic=="RET","ARM64 instruction decode");auto result=e.decompile(e.binary()->entry);check(result["code"].get<std::string>().find("42")!=std::string::npos||result["code"].get<std::string>().find("0x2a")!=std::string::npos,"ARM64 pseudocode semantics");}
auto bad=data;put<uint32_t>(bad,36,0xffffffff);save(path,bad);bool rejected=false;try{Binary b(path);}catch(...){rejected=true;}check(rejected,"Mach-O malformed load command accepted");
std::vector<uint8_t> fat(0x1000+data.size());put<uint32_t>(fat,0,0xbebafeca);put<uint32_t>(fat,4,0x01000000);put<uint32_t>(fat,8,0x0c000001);put<uint32_t>(fat,16,0x00100000);auto sz=uint32_t(data.size());put<uint32_t>(fat,20,(sz>>24)|((sz>>8)&0xff00)|((sz<<8)&0xff0000)|(sz<<24));std::memcpy(fat.data()+0x1000,data.data(),data.size());save(path,fat);{Binary b(path);check(b.format=="Mach-O Universal"&&b.entry==0x100000200&&b.sections[0].offset==0x1000,"Mach-O universal slice mapping");}
data=elf();save(path,data);{Engine e;e.open(path);check(binaryArchitecture(*e.binary())=="arm64"&&e.disassemble(0x400200,2)[1].mnemonic=="RET","ARM64 ELF");}
data.assign(0x240,0);data[0]='M';data[1]='Z';put<uint32_t>(data,0x3c,0x80);put<uint32_t>(data,0x80,0x4550);put<uint16_t>(data,0x84,0xaa64);put<uint16_t>(data,0x86,1);put<uint16_t>(data,0x94,240);put<uint16_t>(data,0x98,0x20b);put<uint32_t>(data,0xa8,0x1000);put<uint64_t>(data,0xb0,0x140000000);put<uint32_t>(data,0xd4,0x200);std::memcpy(data.data()+0x188,".text",5);put<uint32_t>(data,0x190,0x40);put<uint32_t>(data,0x194,0x1000);put<uint32_t>(data,0x198,0x40);put<uint32_t>(data,0x19c,0x200);put<uint32_t>(data,0x1ac,0x60000020);put<uint32_t>(data,0x200,0x52800540);put<uint32_t>(data,0x204,0xd65f03c0);save(path,data);{Engine e;e.open(path);check(binaryArchitecture(*e.binary())=="arm64"&&e.disassemble(0x140001000,2)[1].mnemonic=="RET","ARM64 PE");check(!e.decompile(0x140001000)["code"].get<std::string>().empty(),"ARM64 Windows calling convention");}
const std::vector<std::pair<std::string,std::vector<uint8_t>>> fixtures={{"arm64",{0x02,0,0,0x94,0xc0,3,0x5f,0xd6,0x40,5,0x80,0x52,0xc0,3,0x5f,0xd6}},{"arm",{0x2a,0,0xa0,0xe3,0x1e,0xff,0x2f,0xe1}},{"thumb",{0x2a,0x20,0x70,0x47}},{"riscv32",{0x13,5,0xa0,2,0x67,0x80,0,0}},{"riscv64",{0x13,5,0xa0,2,0x67,0x80,0,0}},{"mips32",{0x2a,0,2,0x24,8,0,0xe0,3,0,0,0,0}},{"mips64",{0x2a,0,2,0x24,8,0,0xe0,3,0,0,0,0}}};
data.resize(0x258);put<uint16_t>(data,0x86,2);put<uint32_t>(data,0x104,16);put<uint32_t>(data,0x120,0x2000);put<uint32_t>(data,0x124,8);std::memcpy(data.data()+0x1b0,".pdata",6);put<uint32_t>(data,0x1b8,8);put<uint32_t>(data,0x1bc,0x2000);put<uint32_t>(data,0x1c0,8);put<uint32_t>(data,0x1c4,0x250);put<uint32_t>(data,0x1d4,0x40000040);put<uint32_t>(data,0x250,0x1010);put<uint32_t>(data,0x254,9);save(path,data);{Binary b(path);auto f=std::find_if(b.functions.begin(),b.functions.end(),[](const Function& f){return f.va==0x140001010;});check(f!=b.functions.end()&&f->end==0x140001018,"ARM64 packed unwind function indexing");}
for(auto&[arch,code]:fixtures){auto padded=code;padded.resize(code.size()+32,0);save(path,padded);Engine e;callArchitecturesTool(e,"open_binary_architecture",{{"path",pathText(path)},{"architecture",arch}});auto rows=e.disassemble(0x1000,4);check(!rows.empty()&&rows[0].mnemonic!="db","Explicit architecture decode");check(binaryArchitecture(*e.binary())==arch,"Explicit architecture detection");if(arch=="arm64"){auto analysis=e.analyze(100);check(analysis["functions_added"]==1&&analysis["complete"]==true,"ARM64 BL target discovery");}else{auto code=e.decompile(0x1000);check(!code["code"].get<std::string>().empty(),"Native pseudocode for explicit architecture");}}
std::filesystem::remove(path);std::cout<<"PASS: ARM64 Mach-O thin/universal bounds, ELF, raw ARM/Thumb/RISC-V/MIPS, direct calls, native pseudocode\n";return 0;}catch(const std::exception& ex){std::cerr<<ex.what()<<'\n';return 1;}}

